function renderChart(rows){styleSqtSummary();try{prepareSqtTable(rows);formatSessionColumns();renderSqtRankings(rows);balanceSqtLayout();balanceCollapsedTable();labelSqtChange()}catch(error){console.warn('SQT table layout could not be enhanced',error)}styleSqtTrend();const root=document.getElementById('sqtChart'),branches=[...new Set(sqtRows.map(row=>row.branch))].sort((a,b)=>a.localeCompare(b));if(!sqtTrendState.branch)sqtTrendState.branch=branches[0]||'';const weeks=availableWeeks(),keys=trendWeekKeys(),points=trendPoints(keys),latest=[...points].reverse().find(point=>point.pct!==null),latestRows=keys.length?aggregate(sqtRows.filter(row=>row.weekKey===keys.at(-1))):[],priority=latestRows.filter(row=>row.pct<80).sort((a,b)=>a.pct-b.pct),scopeLabel=sqtTrendState.scope==='all'?'Overall SQT':sqtTrendState.branch;root.innerHTML=`<div class="trend-header"><div><p class="eyebrow">SQT TREND</p><h2>Weekly SQT performance</h2><p>${sqtTrendState.scope==='all'?'Overall SQT across all reporting centers.':`SQT performance for ${esc(sqtTrendState.branch)}.`}</p></div><div class="trend-latest"><span>${esc(scopeLabel)}</span><strong>${latest?`${latest.pct.toFixed(1)}%`:'—'}</strong></div></div><div class="trend-controls"><div class="filter-switch" role="group" aria-label="Trend view"><button class="${sqtTrendState.scope==='all'?'active':''}" data-trend-scope="all">Show all</button><button class="${sqtTrendState.scope==='branch'?'active':''}" data-trend-scope="branch">Filter by branch</button></div><select class="trend-branch" id="trendBranch" ${sqtTrendState.scope==='branch'?'':'hidden'} aria-label="Select center">${branches.map(branch=>`<option value="${esc(branch)}" ${branch===sqtTrendState.branch?'selected':''}>${esc(branch)}</option>`).join('')}</select><div class="filter-switch" role="group" aria-label="Trend date filter"><button class="${sqtTrendState.mode==='week'?'active':''}" data-trend-mode="week">Filter by week</button><button class="${sqtTrendState.mode==='period'?'active':''}" data-trend-mode="period">Filter by period</button></div><select id="trendWeek" ${sqtTrendState.mode==='week'?'':'hidden'} aria-label="Trend ending week">${weeks.map(week=>`<option value="${esc(week)}" ${week===sqtTrendState.week?'selected':''}>Up to ${esc(weekLabel(week))}</option>`).join('')}</select><div class="trend-period" ${sqtTrendState.mode==='period'?'':'hidden'}><label>From <input id="trendStart" type="date" value="${esc(sqtTrendState.start)}"></label><label>To <input id="trendEnd" type="date" value="${esc(sqtTrendState.end)}"></label><button id="applyTrendPeriod">Apply</button></div></div><div class="trend-layout"><div class="trend-canvas">${trendSvg(points)}</div><aside class="trend-priority"><h3>Priority centers</h3><p>Below the 80% target in ${keys.length?esc(weekLabel(keys.at(-1))):'the selected period'}.</p>${priority.length?`<ol>${priority.map((row,index)=>`<li><span>${index+1}. ${esc(row.branch)}</span><b>${row.pct.toFixed(1)}%</b></li>`).join('')}</ol>`:'<div class="clear">All reporting centers are on track.</div>'}</aside></div>`;root.querySelectorAll('[data-trend-scope]').forEach(button=>button.addEventListener('click',()=>{sqtTrendState.scope=button.dataset.trendScope;renderChart(rows)}));root.querySelectorAll('[data-trend-mode]').forEach(button=>button.addEventListener('click',()=>{sqtTrendState.mode=button.dataset.trendMode;renderChart(rows)}));root.querySelector('#trendBranch')?.addEventListener('change',event=>{sqtTrendState.branch=event.target.value;renderChart(rows)});root.querySelector('#trendWeek')?.addEventListener('change',event=>{sqtTrendState.week=event.target.value;renderChart(rows)});root.querySelector('#applyTrendPeriod')?.addEventListener('click',()=>{sqtTrendState.start=root.querySelector('#trendStart').value;sqtTrendState.end=root.querySelector('#trendEnd').value;renderChart(rows)})}
function renderAnalysis(rows,old,overall){const low=rows.filter(row=>row.pct<80).sort((a,b)=>a.pct-b.pct),decline=rows.map(row=>({...row,d:row.pct-(old.get(row.branch)??row.pct)})).filter(row=>row.d<0).sort((a,b)=>a.d-b.d),label=sqtState.mode==='week'?weekLabel(sqtState.week):'the selected period',gap=Math.max(0,80-overall),attention=low.length?low.slice(0,4).map(row=>`${esc(row.branch)} <b>(${row.pct.toFixed(1)}%)</b>`).join(', '):'All reporting centers are at or above target.',movement=sqtState.mode==='week'&&priorWeek()?(decline.length?`<strong>${esc(decline[0].branch)}</strong> decreased the most, by <strong>${Math.abs(decline[0].d).toFixed(1)} points</strong> from ${esc(weekLabel(priorWeek()))}.`:`No center declined from ${esc(weekLabel(priorWeek()))}.`):'Week-on-week movement is available when filtering by week.',action=low.length?`Prioritize qualified-teacher coverage at the lowest-performing centers, then review session allocation at centers with declining SQT.`:'Maintain current qualified-teacher allocation and monitor for any new decline.';document.getElementById('sqtAnalysis').innerHTML=`<ul class="sqt-analysis-list"><li><span>Overall performance</span><p><strong>${esc(label)}</strong>: <strong>${overall.toFixed(1)}%</strong>${gap?`, which is <strong>${gap.toFixed(1)} points below</strong> the 80% target.`:`, meeting the 80% target.`}</p></li><li><span>Centers needing attention</span><p>${low.length?`<strong>${low.length}</strong> center${low.length>1?'s are':' is'} below target: ${attention}.`:attention}</p></li><li><span>Week-on-week movement</span><p>${movement}</p></li><li><span>Recommended focus</span><p>${action}</p></li></ul>`}
