function teacherKey(center,teacher){return`${branchKey(center)}|${String(teacher||'').trim().toLowerCase()}`}
function makeInactiveTeachers(rows){return new Set(rows.filter(row=>String(row['Input manual Teaching Status']||'').trim().toLowerCase()==='inactive').map(row=>String(row['Teacher Input manual Name']||'').trim().toLowerCase()).filter(Boolean))}
function makeObservationLinks(rows){const links=new Map;rows.slice(1).forEach(row=>{const center=String(row[0]||'').trim();if(!center)return;links.set(branchKey(center),{Q1:String(row[1]||'').trim(),Q2:String(row[2]||'').trim(),Q3:String(row[3]||'').trim(),Q4:String(row[4]||'').trim()})});return links}
function quarterFromDate(date){return date?`Q${Math.floor(date.getMonth()/3)+1}`:''}
function observationLink(center,role,quarter,sourceRole=''){const isCoach=/\bmtc\b|mt\s*coach/i.test(`${role} ${sourceRole}`),links=isCoach?(observationLinks.get(branchKey('MT Coach Indonesia Timur'))||observationLinks.get(branchKey('MTC Indonesia Timur'))):observationLinks.get(branchKey(center));return links?.[quarter]||''}
function makeObservationRoles(raw){const roles=new Map;raw.forEach(row=>{const center=String(row['Data FTE: Center']||'').trim(),teacher=String(row['TEACHER DATABASE [INDONESIA TIMUR] 2026 Name']||'').trim(),role=String(row['Folder All Manual: Role']||'').trim();if(!teacher||!role)return;roles.set(teacherKey(center,teacher),role);const byName=`|${teacher.toLowerCase()}`;if(!roles.has(byName))roles.set(byName,role)});return roles}
function makeObservationTeacherRoster(raw){const unique=new Map;raw.forEach(row=>{const center=String(row['Input Manual Center']||'').trim(),teacher=String(row['Teacher Input manual Name']||'').trim(),role=String(row['Input manual Position/\nRole']||'').trim(),teachingStatus=String(row['Input manual Teaching Status']||'').trim().toUpperCase();if(!center||!teacher||!['MT Local','MT Coach'].includes(role)||teachingStatus==='INACTIVE')return;unique.set(teacherKey(center,teacher),{center,teacher,role})});return[...unique.values()]}
function makeObservationRows(raw){const rosterByKey=new Map(observationTeacherRoster.map(person=>[teacherKey(person.center,person.teacher),person])),rosterByName=new Map(observationTeacherRoster.map(person=>[String(person.teacher).toLowerCase(),person]));return raw.map(row=>{const sourceCenter=String(row['Rumus Center Header']||'').trim(),sourceTeacher=String(row['Rumus Teacher Name Header']||'').trim(),person=rosterByKey.get(teacherKey(sourceCenter,sourceTeacher))||rosterByName.get(sourceTeacher.toLowerCase());if(!person)return null;const date=sheetDate(row['Rumus Observation Date Header']),score=num(row['Rumus Average Score Header']),status=String(row['Data Observation Rumus Observation Status Header']||'').trim()||'Not started',quarter=String(row['Data Source Input manual Q ']||'').trim().toUpperCase()||quarterFromDate(date),link=observationLink(person.center,person.role,quarter,person.role);return{center:person.center,teacher:person.teacher,role:person.role,score,status,quarter,link,date}}).filter(Boolean)}
function latestObservationRows(){const fitsRoster=row=>['MT Local','MT Coach'].includes(row.role)&&(observationState.branch==='all'||row.center===observationState.branch)&&(observationState.role==='all'||row.role===observationState.role),history=observationRows.filter(fitsRoster),latest=rows=>{const map=new Map;rows.forEach(row=>{const key=teacherKey(row.center,row.teacher),old=map.get(key);if(!old||(+row.date||-Infinity)>(+old.date||-Infinity))map.set(key,row)});return map},matches=row=>(observationState.status==='all'||row.status===observationState.status)&&(observationState.qualification==='all'||(observationState.qualification==='qualified'?row.score>=4.1:row.score<4.1)),roster=observationTeacherRoster.filter(fitsRoster),selected=latest(history.filter(row=>observationState.quarter==='all'||row.quarter===observationState.quarter));return roster.map(person=>selected.get(teacherKey(person.center,person.teacher))||{...person,quarter:observationState.quarter==='all'?'':observationState.quarter,status:'No observation',score:0,link:observationState.quarter==='all'?'':observationLink(person.center,person.role,observationState.quarter)}).filter(matches).sort((a,b)=>a.center.localeCompare(b.center)||a.teacher.localeCompare(b.teacher))}
function observationOptions(values,current,allLabel){return`<option value="all">${esc(allLabel)}</option>${values.map(value=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(value)}</option>`).join('')}`}
function observationTitle(active){const title=document.querySelector('#academic .page-title'),link=document.getElementById('academicLink');if(!title)return;if(active){title.querySelector('.eyebrow').textContent='ACADEMIC PERFORMANCE';title.querySelector('h1').innerHTML='Observation <em>Details.</em>';title.querySelector('div>p:not(.eyebrow)').textContent='Latest teacher observation records from the Observation source.';if(link){link.href=sheetUrl(observationSource);link.textContent='Open source ↗'}}else{updateSqtDescription();title.querySelector('h1').innerHTML='Sessions by <em>Qualified Teachers.</em>';if(link){link.href=sheetUrl(sources.academic);link.textContent='Open source ↗'}}}
