function updateObservationDock(){syncAcademicDock(2,observationState.view==='overall'?'Observation Details':'Observation Detail')}
function watchAcademicDock(){const tabs=document.querySelector('#academic .sqt-tabs');if(!tabs||tabs.dataset.dockWatcher)return;tabs.dataset.dockWatcher='true';new MutationObserver(()=>{const buttons=[...tabs.querySelectorAll('.sheet-tab')],active=Math.max(0,buttons.findIndex(button=>button.classList.contains('active')));syncAcademicDock(active,buttons[active]?.textContent||'SQT')}).observe(tabs,{subtree:true,childList:true,attributes:true,attributeFilter:['class']})}
async function renderObservationDetails(){const panel=document.getElementById('observationPanel');if(!panel)return;if(!observationRows.length){panel.innerHTML='<div class="obs-loading">Loading Observation Details…</div>';try{observationRows=makeObservationRows(await loadObservationRecords())}catch(error){console.warn('Observation Details source could not be loaded',error);panel.innerHTML='<div class="obs-empty"><strong>Observation Details could not load yet.</strong><p>Please refresh and try again.</p></div>';return}}const branches=[...new Set(observationTeacherRoster.map(row=>row.center))].sort((a,b)=>a.localeCompare(b)),quarters=[...new Set(observationRows.map(row=>row.quarter).filter(Boolean))].sort(),statuses=[...new Set([...observationRows.map(row=>row.status).filter(Boolean),'No observation'])].sort(),rows=latestObservationRows(),detailReady=observationState.branch!=='all';panel.innerHTML=`<section class="obs-header"><p class="eyebrow">ACADEMIC PERFORMANCE</p><h2>Observation Details</h2><p>Each teacher is shown once, using the latest record in the selected period.</p></section><div class="obs-controls"><div class="filter-switch" role="group" aria-label="Observation view"><button class="${observationState.view==='overall'?'active':''}" data-observation-view="overall">Overall</button><button class="${observationState.view==='detail'?'active':''}" data-observation-view="detail">Detail</button></div><select id="obsBranch" aria-label="Filter by branch">${observationOptions(branches,observationState.branch,'All branches')}</select><select id="obsQuarter" aria-label="Filter by quarter">${observationOptions(quarters,observationState.quarter,'All quarters')}</select><select id="obsQualification" aria-label="Filter by qualification"><option value="all">All qualification</option><option value="qualified" ${observationState.qualification==='qualified'?'selected':''}>Qualified (≥ 4.1)</option><option value="unqualified" ${observationState.qualification==='unqualified'?'selected':''}>Unqualified (&lt; 4.1)</option></select><select id="obsStatus" aria-label="Filter by observation status">${observationOptions(statuses,observationState.status,'All statuses')}</select></div>${observationState.view==='detail'?`<div class="obs-empty obs-detail-empty"><strong>${detailReady?esc(observationState.branch):'Choose a branch to view details.'}</strong><p>${detailReady?'The branch-level detail view is ready for the next step of our design.':'Select a branch from the filter above to begin.'}</p></div>`:`<div class="obs-count">${rows.length} teacher${rows.length===1?'':'s'} shown</div><div class="data-shell obs-table-shell"><div class="table-wrap"><table><thead><tr><th>Branch</th><th>Teacher</th><th>Latest status</th><th>Latest score</th><th>Observation sheet</th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(row.center)}</strong></td><td>${esc(row.teacher)}</td><td><span class="obs-status">${esc(row.status)}</span></td><td>${row.score===null?'<span class="obs-score missing">—</span>':`<span class="obs-score ${row.score>=4.1?'qualified':'unqualified'}">${row.score.toFixed(2)}</span>`}</td><td>${row.link?`<a class="obs-link" href="${esc(row.link)}" target="_blank" rel="noreferrer">Open sheet ↗</a>`:'—'}</td></tr>`).join('')||'<tr><td colspan="5">No teachers match these filters.</td></tr>'}</tbody></table></div></div>`}`;panel.querySelectorAll('[data-observation-view]').forEach(button=>button.addEventListener('click',()=>{observationState.view=button.dataset.observationView;updateObservationDock();renderObservationDetails()}));[['obsBranch','branch'],['obsQuarter','quarter'],['obsQualification','qualification'],['obsStatus','status']].forEach(([id,key])=>panel.querySelector(`#${id}`)?.addEventListener('change',event=>{observationState[key]=event.target.value;renderObservationDetails()}))}
function initObservationDetails(){const academic=document.getElementById('academic'),tabs=academic?.querySelector('.sqt-tabs');if(!academic||!tabs||document.getElementById('observationPanel'))return;const tabButtons=[...tabs.querySelectorAll('.sheet-tab')],sqtPanel=document.createElement('div'),observationPanel=document.createElement('div');sqtPanel.id='sqtPanel';observationPanel.id='observationPanel';observationPanel.hidden=true;const movable=[...academic.children].filter(child=>!child.classList.contains('academic-sticky'));movable.forEach(child=>sqtPanel.append(child));academic.append(sqtPanel,observationPanel);const observationTab=tabButtons[2];observationTab.textContent='Observation Details';observationTab.disabled=false;const show=async mode=>{const isObservation=mode==='observation';localStorage.setItem('acops-academic-tab',isObservation?'observation':'sqt');sqtPanel.hidden=isObservation;observationPanel.hidden=!isObservation;tabButtons.forEach((button,index)=>button.classList.toggle('active',isObservation?index===2:index===0));observationTitle(isObservation);if(isObservation){updateObservationDock();await renderObservationDetails()}else{const dock=document.querySelector('.academic-dock');if(dock){dock.querySelector('strong').innerHTML='Academic performance <span>/ SQT</span>';dock.querySelectorAll('div span').forEach((span,index)=>span.classList.toggle('active',index===0))}}};tabButtons[0].addEventListener('click',()=>show('sqt'));observationTab.addEventListener('click',()=>show('observation'));show(localStorage.getItem('acops-academic-tab')==='observation'?'observation':'sqt')}
function addObservationRoleColumn(){const table=document.querySelector('#observationPanel .obs-table-shell table');if(!table||table.dataset.rolesReady==='true')return;const header=table.querySelector('thead tr'),teacherHeader=[...header.children].find(cell=>cell.textContent.trim()==='Teacher');if(!teacherHeader)return;teacherHeader.insertAdjacentHTML('afterend','<th>Role</th>');const data=latestObservationRows();table.querySelectorAll('tbody tr').forEach((row,index)=>{const cells=[...row.children],item=data[index],role=item?.role||'—';cells[1]?.insertAdjacentHTML('afterend',`<td><span class="obs-role">${esc(role)}</span></td>`);const linkCell=row.lastElementChild,shared=observationLinks.get(branchKey('MT Coach Indonesia Timur'))||observationLinks.get(branchKey('MTC Indonesia Timur')),isCoach=/\bmtc\b|mt\s*coach/i.test(role);if(isCoach&&item&&shared?.[item.quarter]&&linkCell?.textContent.trim()==='—')linkCell.innerHTML=`<a class="obs-link" href="${esc(shared[item.quarter])}" target="_blank" rel="noreferrer">Open sheet ↗</a>`});table.dataset.rolesReady='true'}
function addObservationRoleFilter(){const controls=document.querySelector('#observationPanel .obs-controls'),qualification=controls?.querySelector('#obsQualification');if(!controls||!qualification||controls.querySelector('#obsRole'))return;qualification.insertAdjacentHTML('beforebegin',`<select id="obsRole" aria-label="Filter by role"><option value="all">All roles</option><option value="MT Coach" ${observationState.role==='MT Coach'?'selected':''}>MT Coach</option><option value="MT Local" ${observationState.role==='MT Local'?'selected':''}>MT Local</option></select>`);controls.querySelector('#obsRole').addEventListener('change',event=>{observationState.role=event.target.value;renderObservationDetails()})}
function watchObservationRoles(){const panel=document.getElementById('observationPanel');if(!panel||panel.dataset.roleWatcher)return;panel.dataset.roleWatcher='true';new MutationObserver(()=>{addObservationRoleColumn();addObservationRoleFilter()}).observe(panel,{childList:true,subtree:true})}
function preserveLiveStatus(){if(document.getElementById('lastUpdated'))return;const status=document.createElement('span');status.id='lastUpdated';status.hidden=true;document.body.append(status)}
function fixDockOffset(){if(document.getElementById('dock-offset-fix'))return;const style=document.createElement('style');style.id='dock-offset-fix';style.textContent='.nav-toggle{left:251px;display:flex;align-items:center;justify-content:center;padding:0;font-size:0;line-height:1;text-indent:0}.nav-toggle::after{content:"";box-sizing:border-box;width:10px;height:10px;border-left:3px solid #6256c9;border-bottom:3px solid #6256c9;transform:rotate(45deg)}body.nav-hidden .nav-toggle{left:29px}body.nav-hidden .nav-toggle::after{transform:rotate(225deg)}body.nav-hidden .academic-dock{padding-left:96px}#sqtWeek{-webkit-appearance:none;appearance:none;padding-right:42px;background-image:linear-gradient(45deg,transparent 50%,#272536 50%),linear-gradient(135deg,#272536 50%,transparent 50%);background-position:calc(100% - 22px) 48%,calc(100% - 16px) 48%;background-size:6px 6px,6px 6px;background-repeat:no-repeat}@media(min-width:761px){body.nav-hidden main{padding-left:76px}}@media(max-width:1129px){.nav-toggle{left:205px}}@media(max-width:760px){.nav-toggle{left:auto;right:16px}body.nav-hidden .nav-toggle{left:auto;right:16px}body.nav-hidden .academic-dock{padding-left:76px}}';document.head.append(style)}
function updateSqtDescription(){const eyebrow=document.querySelector('#academic .page-title .eyebrow'),description=document.querySelector('#academic .page-title>div>p:not(.eyebrow)');if(eyebrow)eyebrow.textContent='ACADEMIC PERFORMANCE';if(description)description.textContent='SQT performance data is updated every Monday at around 13.00 WITA.'}
function setView(v){preserveLiveStatus();initLayoutControls();fixDockOffset();hideGlobalSearch();document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id===v));document.querySelectorAll('.nav-link').forEach(e=>e.classList.toggle('active',e.dataset.view===v));if(v==='academic'){updateSqtDescription();initAcademicSticky();initObservationDetails();watchObservationRoles();watchAcademicDock()}if(v==='center')renderLinkBoard()}
function renderLinkBoard(){const t=activeTables.center;if(!t?.rows?.length)return;const u=t.headers.findIndex(h=>/link|url/i.test(h)),n=t.headers.findIndex(h=>/name|title|resource/i.test(h));if(u<0)return;document.getElementById('linkBoard').innerHTML=t.rows.filter(r=>r[u]).slice(0,9).map(r=>`<a class="resource-link" href="${esc(r[u])}" target="_blank" rel="noreferrer"><small>RESOURCE</small>${esc(r[n]||r[u])}<span>↗</span></a>`).join('')}
Object.entries(sources).forEach(([k,s])=>{const l=document.getElementById(`${k}Link`);if(l)l.href=sheetUrl(s)});makeDashboard();['operations','center'].forEach(buildTabs);initSqt();document.getElementById('sqtWeek').addEventListener('change',e=>{sqtState.week=e.target.value;renderSqt()});document.querySelectorAll('[data-filter-mode]').forEach(b=>b.addEventListener('click',()=>{sqtState.mode=b.dataset.filterMode;document.querySelectorAll('[data-filter-mode]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('weekFilter').hidden=sqtState.mode!=='week';document.getElementById('periodFilter').hidden=sqtState.mode!=='period';renderSqt()}));document.getElementById('applyPeriod').addEventListener('click',()=>{sqtState.start=document.getElementById('sqtStart').value;sqtState.end=document.getElementById('sqtEnd').value;renderSqt()});document.getElementById('sqtSearch').addEventListener('input',e=>{sqtState.search=e.target.value;renderSqt()});document.getElementById('sqtSort').addEventListener('change',e=>{sqtState.sort=e.target.value;renderSqt()});document.getElementById('exportSqt').addEventListener('click',exportSqt);window.addEventListener('hashchange',()=>setView(location.hash.slice(1)||'dashboard'));setView(location.hash.slice(1)||'dashboard');
